 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Logging;
 using OpenAI;

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable to run this agent.");

 var services = new ServiceCollection();
 services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Information));
 services.AddChatClient(sp =>
     new OpenAIClient(apiKey).GetChatClient("gpt-4o-mini-2024-07-18").AsIChatClient());

 var sp = services.BuildServiceProvider();
 var chatClient = sp.GetRequiredService<IChatClient>();
 var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

 // Define tools
 var researchTools = new ResearchTools();
 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(researchTools.SearchWeb),
     AIFunctionFactory.Create(researchTools.TakeNote),
     AIFunctionFactory.Create(researchTools.GetNotes),
 };

 // Create the agent
 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research agent. Your job is to research a topic thoroughly by:
         1. Searching the web for relevant information using multiple queries.
         2. Taking notes on key findings as you discover them.
         3. After gathering enough information, reviewing your notes and providing
            a comprehensive summary with sources.

         Always take notes on important findings before moving to the next search.
         Aim for at least 2-3 searches to cover different aspects of the topic.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes",
     tools: tools,
     loggerFactory: loggerFactory,
     services: sp);

 // Determine the research topic
 var topic = args.Length > 0
     ? string.Join(' ', args)
     : "recent advances in quantum computing 2025";

 Console.WriteLine($"🔍 Researching: {topic}\n");

 // Create a session and run the agent
 var session = await agent.CreateSessionAsync();

 await foreach (var update in agent.RunStreamingAsync(
     $"Research the following topic and provide a summary: {topic}",
     session))
 {
     if (!string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine("\n\n📝 Research complete.");

 // --- Tool implementations ---

 public sealed class ResearchTools
 {
     private readonly List<string> _notes = [];
     private readonly HttpClient _httpClient = new();

     [Description("Search the web for information on a query. Returns a list of search results with titles, snippets, and URLs.")]
     public async Task<string> SearchWeb(
         [Description("The search query to look up")] string query)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var response = await _httpClient.GetFromJsonAsync<JsonElement>(url);

             var results = new List<string>();

             var abstractText = response.GetProperty("Abstract").GetString();
             var abstractUrl = response.GetProperty("AbstractURL").GetString();
             if (!string.IsNullOrWhiteSpace(abstractText))
             {
                 results.Add($"[Summary] {abstractText} (Source: {abstractUrl})");
             }

             if (response.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var item in topics.EnumerateArray().Take(5))
                 {
                     if (item.TryGetProperty("Text", out var text) &&
                         item.TryGetProperty("FirstURL", out var topicUrl))
                     {
                         results.Add($"- {text.GetString()} (Source: {topicUrl.GetString()})");
                     }
                 }
             }

             if (results.Count == 0)
             {
                 results.Add($"No detailed results found for '{query}'. Try a different search query.");
             }

             return string.Join("\n", results);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note. Use this to record important findings during research.")]
     public string TakeNote(
         [Description("The note content to save")] string note,
         [Description("The source URL or reference for this note")] string source = "unknown")
     {
         var entry = $"[{_notes.Count + 1}] {note} (Source: {source})";
         _notes.Add(entry);
         Console.WriteLine($"  📌 Note taken: {note[..Math.Min(note.Length, 60)]}...");
         return $"Note saved successfully. You now have {_notes.Count} note(s).";
     }

     [Description("Retrieve all notes taken so far during this research session.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
         {
             return "No notes taken yet.";
         }

         return $"Research notes ({_notes.Count} total):\n{string.Join("\n", _notes)}";
     }
 }
